effect.shader:
float hash2(vec2 c) {
    c += vec2(float(seed) * 13.7);
    return fract(sin(dot(c, vec2(127.1, 311.7))) * 43758.5453);
}

void main() {
    // Quadro rítmico: congela o glitch por 1/rate segundos; muda só nas trocas.
    float quadro = floor(acTime * rate);

    // Índice da faixa deste pixel.
    float n = max(float(int(bandCount + 0.5)), 1.0);
    float faixa = floor(acScreenNorm.y * n);

    // Essa faixa, nesse quadro, está glitchando?
    float sorteia = hash2(vec2(faixa, quadro));
    float deslocamento = 0.0;
    if (sorteia < chance) {
        // Sim: pula; a direção e a força vêm de outro hash.
        float quanto = (hash2(vec2(faixa, quadro + 7.0)) * 2.0 - 1.0) * jumpAmount;
        deslocamento = quanto;
    }

    vec2 uv = acScreenNorm + vec2(deslocamento, 0.0);

    // Separação RGB: cada canal lê em UV ligeiramente diferente.
    float sep = rgbSplit * 0.003 * abs(deslocamento) * 20.0;  // split maior onde o glitch é maior
    float r = texture(inputImg, uv + vec2(sep, 0.0)).r;
    float g = texture(inputImg, uv).g;
    float b = texture(inputImg, uv - vec2(sep, 0.0)).b;
    float a = texture(inputImg, uv).a;

    fragColor = vec4(r, g, b, a);
}
